const settings = $("Settings").first().json;
const rawConfigRows = $("Read Configuration").all().map((item) => item.json);
const rawProfileRows = $("Read Profiles for Diagnostic").all().map((item) => item.json);
const configRows = rawConfigRows.filter((row) => row && row.id);
const profileRows = rawProfileRows.filter((row) => row && row.id);
const blockers = [];

if (!settings.spreadsheetId || String(settings.spreadsheetId).startsWith("PASTE_")) {
  blockers.push("spreadsheetId is not set: open the Settings node and paste the Google Sheet id.");
}
if (profileRows.length === 0) {
  blockers.push("No profile found: run the import_cv action first.");
}

const configuration = configRows.length > 0 ? configRows[0] : null;
const lastProfile = profileRows.length > 0 ? profileRows[profileRows.length - 1] : null;

return [{
  json: {
    status: blockers.length === 0 ? "ready" : "incomplete",
    action: "diagnostic",
    blockers,
    integrations: {
      google_sheets: { status: "ready", detail: "Reading the Configuration and Profiles sheets succeeded." },
      gemini: { status: "not_verified", detail: "Checked on the first import_cv or prepare run. Target model: Gemini Flash-Lite latest." },
      gmail: { status: "not_connected", detail: "This workflow never calls Gmail. It stores draft content only." }
    },
    configuration_rows: configRows.length,
    profile: lastProfile ? { id: lastProfile.id, human_verified: lastProfile.human_verified } : null,
    configuration_present: configuration !== null,
    rules: {
      automatic_email: "disabled",
      draft_only: true,
      human_validation: "required for every generated document"
    },
    checked_at: new Date().toISOString()
  }
}];

const input = $("Application Form").first().json;
const cv = String(input.cv_text || "").trim();

if (cv.length < 50) {
  throw new Error("cv_text is empty or too short (minimum 50 characters). Paste the CV text in the form.");
}

return [{ json: { cvText: cv.slice(0, 12000), truncated: cv.length > 12000 } }];

const payload = $input.first().json;
const settings = $("Settings").first().json;
const cv = $("Validate Cv Input").first().json;
function extractGeminiText(payload) {
  if (!payload) { return ""; }
  if (typeof payload === "string") { return payload; }
  if (typeof payload.text === "string" && payload.text.length > 0) { return payload.text; }
  if (typeof payload.content === "string") { return payload.content; }
  if (payload.content && Array.isArray(payload.content.parts)) {
    return payload.content.parts.map((part) => (part && typeof part.text === "string") ? part.text : "").join("");
  }
  if (Array.isArray(payload.parts)) {
    return payload.parts.map((part) => (part && typeof part.text === "string") ? part.text : "").join("");
  }
  if (payload.content && typeof payload.content === "object") { return JSON.stringify(payload.content); }
  return JSON.stringify(payload);
}

if (payload && payload.finishReason && payload.finishReason !== "STOP") {
  throw new Error("Gemini stopped early (" + payload.finishReason + "). Reduce the prompt size or raise maxOutputTokens.");
}

const raw = extractGeminiText(payload);
const start = raw.indexOf("{");
const end = raw.lastIndexOf("}");

if (start === -1 || end === -1) {
  throw new Error("Gemini did not return JSON. First 200 characters: " + raw.slice(0, 200));
}

let parsed;
try {
  parsed = JSON.parse(raw.slice(start, end + 1));
} catch (error) {
  throw new Error("Gemini returned invalid JSON: " + error.message);
}

if (!parsed.personal_info || typeof parsed.personal_info !== "object") {
  throw new Error("The profile JSON has no personal_info object. Re-run import_cv.");
}

const confidence = Number(parsed.extraction_confidence);
const now = new Date().toISOString();

return [{
  json: {
    id: "profile-" + settings.userId,
    user_id: settings.userId,
    version: 1,
    source_filename: "form-upload",
    extracted_at: now,
    personal_info_json: JSON.stringify(parsed.personal_info || {}),
    education_json: JSON.stringify(parsed.education || []),
    experience_json: JSON.stringify(parsed.experience || []),
    skills_json: JSON.stringify(parsed.skills || []),
    languages_json: JSON.stringify(parsed.languages || []),
    certifications_json: JSON.stringify(parsed.certifications || []),
    projects_json: JSON.stringify(parsed.projects || []),
    raw_text: cv.cvText,
    extraction_confidence: isNaN(confidence) ? 0 : confidence,
    uncertain_elements_json: JSON.stringify(parsed.uncertain_elements || []),
    human_verified: false,
    created_at: now,
    updated_at: now
  }
}];

const input = $("Application Form").first().json;
const settings = $("Settings").first().json;
const title = String(input.offer_title || "").trim();
const company = String(input.company_name || "").trim();
const description = String(input.offer_description || "").trim();

if (title.length < 2 || company.length < 2) {
  throw new Error("offer_title and company_name are required to add an offer.");
}
if (description.length < 40) {
  throw new Error("offer_description is too short (minimum 40 characters). Paste the offer text.");
}

let hash = 5381;
const key = (company + "|" + title).toLowerCase();
for (let index = 0; index < key.length; index = index + 1) {
  hash = ((hash * 33) ^ key.charCodeAt(index)) >>> 0;
}
const offerId = "offer-" + hash.toString(16);
const now = new Date().toISOString();

return [{
  json: {
    id: offerId,
    user_id: settings.userId,
    external_id: offerId,
    external_source: "manual",
    title: title,
    company_name: company,
    company_domain: String(input.company_domain || "").trim().toLowerCase(),
    description: description.slice(0, 12000),
    location: String(input.location || "").trim(),
    contact_email: String(input.contact_email || "").trim(),
    status: "new",
    availability_status: "available",
    created_at: now,
    updated_at: now
  }
}];

const input = $("Application Form").first().json;
const settings = $("Settings").first().json;
const offers = $("Read Offers for Prepare").all().map((item) => item.json).filter((row) => row && row.id);
const profiles = $("Read Profiles for Prepare").all().map((item) => item.json).filter((row) => row && row.id);

if (profiles.length === 0) {
  throw new Error("No profile found: run the import_cv action first.");
}
if (offers.length === 0) {
  throw new Error("No offer found: run the add_offer action first.");
}

const reference = String(input.offer_ref || "").trim().toLowerCase();
let offer = null;

if (reference.length > 0) {
  offer = offers.find((row) => String(row.id).toLowerCase() === reference) || null;
  if (!offer) {
    offer = offers.find((row) => String(row.company_name || "").toLowerCase() === reference) || null;
  }
  if (!offer) {
    offer = offers.find((row) => String(row.title || "").toLowerCase().indexOf(reference) !== -1) || null;
  }
  if (!offer) {
    throw new Error("No offer matches this reference. Use the offer id or the company name shown by add_offer.");
  }
} else {
  if (offers.length > 1) {
    throw new Error("Several offers exist: fill offer_ref with the offer id or the company name.");
  }
  offer = offers[0];
}

const profile = profiles[profiles.length - 1];
const randomPart = Math.random().toString(16).slice(2, 10);
const trackingRef = "APP-" + randomPart;
const applicationId = "app-" + trackingRef.slice(4);

return [{
  json: {
    applicationId: applicationId,
    trackingRef: trackingRef,
    offerId: offer.id,
    profileId: profile.id,
    offerJson: JSON.stringify({
      id: offer.id,
      title: offer.title,
      company_name: offer.company_name,
      company_domain: offer.company_domain,
      location: offer.location,
      contact_email: offer.contact_email,
      description: offer.description
    }),
    profileJson: JSON.stringify({
      id: profile.id,
      personal_info: profile.personal_info_json,
      education: profile.education_json,
      experience: profile.experience_json,
      skills: profile.skills_json,
      languages: profile.languages_json,
      certifications: profile.certifications_json,
      projects: profile.projects_json
    })
  }
}];

const payload = $input.first().json;
const context = $("Select Context").first().json;
const settings = $("Settings").first().json;
function extractGeminiText(payload) {
  if (!payload) { return ""; }
  if (typeof payload === "string") { return payload; }
  if (typeof payload.text === "string" && payload.text.length > 0) { return payload.text; }
  if (typeof payload.content === "string") { return payload.content; }
  if (payload.content && Array.isArray(payload.content.parts)) {
    return payload.content.parts.map((part) => (part && typeof part.text === "string") ? part.text : "").join("");
  }
  if (Array.isArray(payload.parts)) {
    return payload.parts.map((part) => (part && typeof part.text === "string") ? part.text : "").join("");
  }
  if (payload.content && typeof payload.content === "object") { return JSON.stringify(payload.content); }
  return JSON.stringify(payload);
}

if (payload && payload.finishReason && payload.finishReason !== "STOP") {
  throw new Error("Gemini stopped early (" + payload.finishReason + "). Reduce the prompt size or raise maxOutputTokens.");
}

const raw = extractGeminiText(payload);
const start = raw.indexOf("{");
const end = raw.lastIndexOf("}");

if (start === -1 || end === -1) {
  throw new Error("Gemini did not return JSON. First 200 characters: " + raw.slice(0, 200));
}

let result;
try {
  result = JSON.parse(raw.slice(start, end + 1));
} catch (error) {
  throw new Error("Gemini returned invalid JSON: " + error.message);
}

const allowed = ["apply", "consider", "skip"];
const recommendation = allowed.indexOf(result.recommendation) === -1 ? "consider" : result.recommendation;
let score = Math.round(Number(result.score));
if (isNaN(score)) { score = 0; }
if (score < 0) { score = 0; }
if (score > 100) { score = 100; }

const cv = String(result.cv_markdown || "");
const missing = Array.isArray(result.missing_skills) ? result.missing_skills : [];
const warnings = Array.isArray(result.warnings) ? result.warnings.slice() : [];

missing.forEach((skill) => {
  const needle = String(skill).toLowerCase().trim();
  if (needle.length > 2 && cv.toLowerCase().indexOf(needle) !== -1) {
    warnings.push("Truthfulness check: missing skill listed in the generated CV: " + skill);
  }
});
if (recommendation === "skip" && cv.length > 0) {
  warnings.push("Truthfulness check: a CV was produced for a skip recommendation.");
}

const now = new Date().toISOString();
const suffix = context.trackingRef.slice(4);
const documents = [];

if (cv.length > 0) {
  documents.push({
    id: "doc-" + suffix + "-cv",
    application_id: context.applicationId,
    profile_id: context.profileId,
    user_id: settings.userId,
    document_type: "cv",
    format: "markdown",
    filename: context.trackingRef + "-cv.md",
    content: cv,
    verification_status: "pending_review",
    human_verified: false,
    created_at: now
  });
}
if (String(result.cover_letter || "").length > 0) {
  documents.push({
    id: "doc-" + suffix + "-letter",
    application_id: context.applicationId,
    profile_id: context.profileId,
    user_id: settings.userId,
    document_type: "cover_letter",
    format: "text",
    filename: context.trackingRef + "-lettre.txt",
    content: String(result.cover_letter),
    verification_status: "pending_review",
    human_verified: false,
    created_at: now
  });
}
if (String(result.email_body || "").length > 0) {
  documents.push({
    id: "doc-" + suffix + "-email",
    application_id: context.applicationId,
    profile_id: context.profileId,
    user_id: settings.userId,
    document_type: "email",
    format: "text",
    filename: context.trackingRef + "-email.txt",
    content: String(result.email_body),
    verification_status: "pending_review",
    human_verified: false,
    created_at: now
  });
}

return [{
  json: {
    application: {
      id: context.applicationId,
      user_id: settings.userId,
      offer_id: context.offerId,
      profile_id: context.profileId,
      tracking_ref: context.trackingRef,
      status: "documents_ready",
      score: score,
      recommendation: recommendation,
      company_name: "",
      offer_title: "",
      contact_email: "",
      email_subject: String(result.email_subject || ""),
      email_body: String(result.email_body || ""),
      draft_status: "not_created",
      sent_at: "",
      created_at: now,
      updated_at: now
    },
    analysis: {
      id: "analysis-" + suffix,
      application_id: context.applicationId,
      offer_id: context.offerId,
      profile_id: context.profileId,
      user_id: settings.userId,
      score: score,
      recommendation: recommendation,
      rationale: String(result.rationale || ""),
      matching_skills_json: JSON.stringify(result.matching_skills || []),
      missing_skills_json: JSON.stringify(missing),
      strengths_json: JSON.stringify(result.strengths || []),
      concerns_json: JSON.stringify(result.concerns || []),
      warnings_json: JSON.stringify(warnings),
      analyzed_by: "gemini-flash-lite-latest",
      created_at: now
    },
    documents: documents,
    summary: {
      tracking_ref: context.trackingRef,
      score: score,
      recommendation: recommendation,
      warning_count: warnings.length,
      document_count: documents.length
    }
  }
}];

const parsed = $("Parse Application").first().json;
const offers = $("Read Offers for Prepare").all().map((item) => item.json);
const offer = offers.find((row) => row.id === parsed.application.offer_id) || {};
const application = parsed.application;

application.company_name = offer.company_name || "";
application.offer_title = offer.title || "";
application.contact_email = offer.contact_email || "";
application.location = offer.location || "";

return [{ json: application }];

const parsed = $("Parse Application").first().json;
const documents = Array.isArray(parsed.documents) ? parsed.documents : [];

if (documents.length === 0) {
  throw new Error("No document was generated. The recommendation may be skip, or the model returned empty content.");
}

return documents.map((document) => ({ json: document }));

const input = $("Application Form").first().json;
const settings = $("Settings").first().json;
const rows = $("Read Applications for Draft").all().map((item) => item.json).filter((row) => row && row.tracking_ref);

if (rows.length === 0) {
  throw new Error("No application found: run the prepare action first.");
}

const reference = String(input.application_ref || "").trim().toLowerCase();
let application = null;

if (reference.length > 0) {
  application = rows.find((row) => String(row.tracking_ref).toLowerCase() === reference) || null;
  if (!application) {
    throw new Error("No application matches this reference. Use the tracking_ref shown by prepare.");
  }
} else {
  application = rows[rows.length - 1];
}

if (String(application.status) === "sent") {
  throw new Error("This application is already marked as sent. A draft is not created again.");
}

const contact = String(application.contact_email || "").trim();
if (contact.length === 0) {
  throw new Error("No contact email on this application. Add the contact email with add_offer before drafting.");
}

const body = String(application.email_body || "").trim();
if (body.length === 0) {
  throw new Error("This application has no email body. Re-run prepare for this offer.");
}

const trackingRef = String(application.tracking_ref);
const baseSubject = String(application.email_subject || "").trim();
const subject = (baseSubject.length > 0 ? baseSubject : "Candidature " + String(application.offer_title || "")) + " - " + trackingRef;
const now = new Date().toISOString();

return [{
  json: {
    id: application.id,
    user_id: application.user_id || settings.userId,
    offer_id: application.offer_id,
    profile_id: application.profile_id,
    tracking_ref: trackingRef,
    status: "draft_ready",
    score: application.score,
    recommendation: application.recommendation,
    company_name: application.company_name,
    offer_title: application.offer_title,
    contact_email: contact,
    email_subject: application.email_subject,
    email_body: body,
    draft_to: contact,
    draft_subject: subject.slice(0, 180),
    draft_body: body,
    draft_status: "ready_manual_send",
    sent_at: application.sent_at || "",
    created_at: application.created_at,
    updated_at: now,
    instructions: "Open your mailbox, create a message with this recipient and subject, attach the reviewed CV, read it, then send it yourself. This workflow never sends."
  }
}];

const rows = $("Read Applications for Dashboard").all().map((item) => item.json).filter((row) => row && row.tracking_ref);
const counts = {};

rows.forEach((row) => {
  const key = String(row.status || "unknown");
  counts[key] = (counts[key] || 0) + 1;
});

const open = rows.filter((row) => ["documents_ready", "draft_ready"].indexOf(String(row.status)) !== -1);
const awaitingSend = rows.filter((row) => String(row.status) === "draft_ready").length;
const sent = rows.filter((row) => String(row.status) === "sent").length;

const applications = rows.map((row) => ({
  tracking_ref: row.tracking_ref,
  company: row.company_name,
  offer: row.offer_title,
  status: row.status,
  score: Number(row.score),
  recommendation: row.recommendation,
  draft_subject: row.draft_subject || "",
  updated_at: row.updated_at
}));

applications.sort((left, right) => Number(right.score) - Number(left.score));

return [{
  json: {
    action: "dashboard",
    total: rows.length,
    counts: counts,
    open_count: open.length,
    awaiting_manual_send: awaitingSend,
    sent_confirmed: sent,
    applications: applications,
    reminder: "A draft is not a sent application. Mark it sent yourself only after the mailbox confirms it.",
    generated_at: new Date().toISOString()
  }
}];
